func (this *GC) FillArcInPixels(x int32, y int32, width int32, height int32, startAngle int32, arcAngle int32) {
	this.CheckNonDisposed()
	this.CheckGC(GCFILL)
	if width < 0 {
		x = x + width
		width = -width
	}
	if height < 0 {
		y = y + height
		height = -height
	}
	if width == 0 || height == 0 || arcAngle == 0 {
		return
	}
	var gdipGraphics int64 = this.data.GdipGraphics
	if gdipGraphics != 0 {
		if width == height {
			win32.GdipGraphics_FillPie(gdipGraphics, this.data.GdipBrush, x, y, width, height, float32(-startAngle), float32(-arcAngle))
		} else {
			var state int32 = win32.GdipGraphics_Save(gdipGraphics)
			win32.GdipGraphics_TranslateTransform(gdipGraphics, float32(x), float32(y), win32.GdipMatrixOrderPrepend)
			win32.GdipGraphics_ScaleTransform(gdipGraphics, float32(width), float32(height), win32.GdipMatrixOrderPrepend)
			win32.GdipGraphics_FillPie(gdipGraphics, this.data.GdipBrush, 0, 0, 1, 1, float32(-startAngle), float32(-arcAngle))
			win32.GdipGraphics_Restore(gdipGraphics, state)
		}
		return
	}
	if (this.data.Style & MIRRORED) != 0 {
		x--
	}
	var x1 int32
	var y1 int32
	var x2 int32
	var y2 int32
	var tmp int32
	var isNegative bool
	if arcAngle >= 360 || arcAngle <= -360 {
		x2 = x + width
		x1 = x2
		y2 = y + height/2
		y1 = y2
	} else {
		isNegative = arcAngle < 0
		arcAngle = arcAngle + startAngle
		if isNegative {
			tmp = startAngle
			startAngle = arcAngle
			arcAngle = tmp
		}
		x1 = GCCos(startAngle, width) + x + width/2
		y1 = -1*GCSin(startAngle, height) + y + height/2
		x2 = GCCos(arcAngle, width) + x + width/2
		y2 = -1*GCSin(arcAngle, height) + y + height/2
	}
	win32.OSPie(this.Handle, x, y, x+width+1, y+height+1, x1, y1, x2, y2)
}

