func (this *GC) FillGradientRectangleInPixels(x int32, y int32, width int32, height int32, vertical bool, zoom int32) {
	if width == 0 || height == 0 {
		return
	}
	var backgroundRGB *RGB
	var foregroundRGB *RGB
	backgroundRGB = this.GetBackground().GetRGB()
	foregroundRGB = this.GetForeground().GetRGB()
	var fromRGB *RGB
	var toRGB *RGB
	fromRGB = foregroundRGB
	toRGB = backgroundRGB
	var swapColors bool = false
	if width < 0 {
		x += width
		width = -width
		if !vertical {
			swapColors = true
		}
	}
	if height < 0 {
		y += height
		height = -height
		if vertical {
			swapColors = true
		}
	}
	if swapColors {
		fromRGB = backgroundRGB
		toRGB = foregroundRGB
	}
	if fromRGB.Equals(toRGB) {
		this.FillRectangleInPixels(x, y, width, height)
		return
	}
	if this.data.GdipGraphics != 0 {
		this.InitGdip()
		var p1 *win32.PointF = win32.NewPointF()
		var p2 *win32.PointF = win32.NewPointF()
		p1.X = float32(x)
		p1.Y = float32(y)
		if vertical {
			p2.X = p1.X
			p2.Y = p1.Y + float32(height)
		} else {
			p2.X = p1.X + float32(width)
			p2.Y = p1.Y
		}
		var fromGpColor int32 = (this.data.Alpha << 24) | ((fromRGB.Red & 0xFF) << 16) | ((fromRGB.Green & 0xFF) << 8) | (fromRGB.Blue & 0xFF)
		var toGpColor int32 = (this.data.Alpha << 24) | ((toRGB.Red & 0xFF) << 16) | ((toRGB.Green & 0xFF) << 8) | (toRGB.Blue & 0xFF)
		var brush int64 = win32.GdipLinearGradientBrush_new(p1, p2, fromGpColor, toGpColor)
		win32.GdipGraphics_FillRectangle(this.data.GdipGraphics, brush, x, y, width, height)
		win32.GdipLinearGradientBrush_delete(brush)
		return
	}
	if win32.OSGetROP2(this.Handle) != win32.OSR2_XORPEN && win32.OSGetDeviceCaps(this.Handle, win32.OSTECHNOLOGY) != win32.OSDT_RASPRINTER {
		var hHeap int64 = win32.OSGetProcessHeap()
		var pMesh int64 = win32.OSHeapAlloc(hHeap, win32.OSHEAP_ZERO_MEMORY, win32.GRADIENT_RECTSizeof+win32.TRIVERTEXSizeof*2)
		if pMesh == 0 {
			Error(ERROR_NO_HANDLES)
		}
		var pVertex int64 = pMesh + int64(win32.GRADIENT_RECTSizeof)
		var gradientRect *win32.GRADIENT_RECT = win32.NewGRADIENT_RECT()
		gradientRect.UpperLeft = 0
		gradientRect.LowerRight = 1
		win32.OSMoveMemoryOverload17(pMesh, gradientRect, win32.GRADIENT_RECTSizeof)
		var trivertex *win32.TRIVERTEX = win32.NewTRIVERTEX()
		trivertex.X = x
		trivertex.Y = y
		trivertex.Red = int16(((fromRGB.Red << 8) | fromRGB.Red))
		trivertex.Green = int16(((fromRGB.Green << 8) | fromRGB.Green))
		trivertex.Blue = int16(((fromRGB.Blue << 8) | fromRGB.Blue))
		trivertex.Alpha = int16(-1)
		win32.OSMoveMemoryOverload27(pVertex, trivertex, win32.TRIVERTEXSizeof)
		trivertex.X = x + width
		trivertex.Y = y + height
		trivertex.Red = int16(((toRGB.Red << 8) | toRGB.Red))
		trivertex.Green = int16(((toRGB.Green << 8) | toRGB.Green))
		trivertex.Blue = int16(((toRGB.Blue << 8) | toRGB.Blue))
		trivertex.Alpha = int16(-1)
		win32.OSMoveMemoryOverload27(pVertex+int64(win32.TRIVERTEXSizeof), trivertex, win32.TRIVERTEXSizeof)
		var cond356 int32
		if vertical {
			cond356 = win32.OSGRADIENT_FILL_RECT_V
		} else {
			cond356 = win32.OSGRADIENT_FILL_RECT_H
		}
		var success bool = win32.OSGradientFill(this.Handle, pVertex, 2, pMesh, 1, cond356)
		win32.OSHeapFree(hHeap, 0, pMesh)
		if success {
			return
		}
	}
	var depth int32 = win32.OSGetDeviceCaps(this.Handle, win32.OSBITSPIXEL)
	var bitResolution int32
	if depth >= 24 {
		bitResolution = 8
	} else {
		var cond357 int32
		if depth >= 15 {
			cond357 = 5
		} else {
			cond357 = 0
		}
		bitResolution = cond357
	}
	ImageDataFillGradientRectangle(this, this.data.Device, x, y, width, height, vertical, fromRGB, toRGB, bitResolution, bitResolution, bitResolution, zoom)
}

