func (this *GC) FillPolygonInPixels(pointArray []int32) {
	this.CheckNonDisposed()
	this.CheckGC(GCFILL)
	if this.data.GdipGraphics != 0 {
		var mode int32
		if win32.OSGetPolyFillMode(this.Handle) == win32.OSWINDING {
			mode = win32.GdipFillModeWinding
		} else {
			mode = win32.GdipFillModeAlternate
		}
		var offsetCorrection float32 = 0.5
		win32.GdipGraphics_TranslateTransform(this.data.GdipGraphics, this.data.GdipXOffset+offsetCorrection, this.data.GdipYOffset+offsetCorrection, win32.GdipMatrixOrderPrepend)
		win32.GdipGraphics_FillPolygon(this.data.GdipGraphics, this.data.GdipBrush, pointArray, int32(len(pointArray))/2, mode)
		win32.GdipGraphics_TranslateTransform(this.data.GdipGraphics, -(this.data.GdipXOffset + offsetCorrection), -(this.data.GdipYOffset + offsetCorrection), win32.GdipMatrixOrderPrepend)
		return
	}
	if (this.data.Style & MIRRORED) != 0 {
		for i := int32(0); i < int32(len(pointArray)); i += 2 {
			pointArray[i]--
		}
	}
	win32.OSPolygon(this.Handle, pointArray, int32(len(pointArray))/2)
	if (this.data.Style & MIRRORED) != 0 {
		for i := int32(0); i < int32(len(pointArray)); i += 2 {
			pointArray[i]++
		}
	}
}
